const e=value=>String(value??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const money=value=>new Intl.NumberFormat("tr-TR",{style:"currency",currency:"TRY"}).format(Number(value||0));
const date=value=>value?new Intl.DateTimeFormat("tr-TR",{dateStyle:"long"}).format(new Date(value)):"Henüz yok";
export function partnerPanelView({summary,referrals=[],commissions=[]}){if(!summary)return `<section class="card teacher-partner-card"><h2>Öğretmen Partner Programı</h2><p>Ücretsiz partner profilinizi oluşturup kod başvurunuzu başlatın.</p><button class="button primary" data-action="register-teacher-partner">Partner profilini oluştur</button></section>`;
 const locked=!summary.has_full_access;return `<section class="teacher-partner" data-teacher-partner-panel><div class="page-head"><div><p class="eyebrow">ÖĞRETMEN PARTNER</p><h1>Partner ve erişim merkezi</h1><p>Partner paneliniz erişim süreniz bitse de açık kalır.</p></div></div>${locked?`<article class="card feedback incorrect"><strong>Tam öğretmen erişiminiz sona erdi.</strong><p>Yeni bir ücretli öğrenci getirerek 30 gün kazanabilir veya 199 TL ile bir ay uzatabilirsiniz.</p></article>`:""}<div class="partner-grid"><article class="card"><h2>Partner kodu</h2><strong class="partner-code" data-partner-code>${e(summary.partner_code)}</strong><div class="button-row"><button class="button primary" data-action="copy-partner-code">Kodu kopyala</button><button class="button secondary" data-action="copy-partner-link">Bağlantıyı kopyala</button></div></article><article class="card"><h2>Erişim</h2><p>Kazanılan: <strong>${e(summary.earned_access_days)} gün</strong></p><p>Kalan: <strong>${e(summary.remaining_access_days)} gün</strong></p><p>Bitiş: <strong>${date(summary.access_ends_at)}</strong></p><button class="button primary" data-action="buy-teacher-monthly">199 TL ile 1 ay uzat</button></article><article class="card"><h2>Satışlar</h2><p>Toplam farklı öğrenci: <strong>${e(summary.total_students)}</strong></p><p>Bu ay: <strong>${e(summary.students_this_month)}</strong></p></article><article class="card"><h2>Komisyon</h2><p>Toplam: <strong>${money(summary.total_commission)}</strong></p><p>Bekleyen: <strong>${money(summary.payable_commission)}</strong></p><p>Ödenmiş: <strong>${money(summary.paid_commission)}</strong></p></article></div><section class="card"><h2>Son hareketler</h2>${commissions.length?commissions.slice(0,10).map(x=>`<p>${date(x.earned_at)} · ${money(x.commission_amount)} · ${e(x.status)}</p>`).join(""):"<p>Henüz komisyon hareketi yok.</p>"}<p class="meta">Nitelikli öğrenci hareketi: ${referrals.length}</p></section></section>`}
export function teacherAccessLockView(){return `<section class="card teacher-access-lock"><h1>Tam öğretmen erişiminiz sona erdi.</h1><p>Yeni bir ücretli öğrenci getirerek 30 gün kazanabilir veya 199 TL ile bir ay uzatabilirsiniz.</p><button class="button primary" data-route="teacher">Partner paneline dön</button></section>`}
